@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--bg:#101510;--panel:#1a211a;--panel2:#222b22;--line:#303a2f;--muted:#9ba69a;--white:#f4f3e8;--lime:#c7f36b;--green:#84bb43;--orange:#ff814f;--gold:#ffcc70;--red:#f47772;--blue:#82c9ed}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--white);font-family:'DM Sans',sans-serif;min-height:100vh;background-image:radial-gradient(ellipse at 70% -10%,#293923 0,transparent 34%),radial-gradient(ellipse at 5% 90%,#182319 0,transparent 26%)}button,select{font:inherit}button{cursor:pointer;color:inherit;border:0}button:focus-visible,select:focus-visible{outline:2px solid var(--lime);outline-offset:3px}.shell{max-width:1450px;margin:auto;padding:0 36px 40px}.topbar{height:78px;border-bottom:1px solid #ffffff12;display:flex;align-items:center;justify-content:space-between;gap:22px}.brand{display:flex;align-items:center;gap:11px;font-weight:900;letter-spacing:1.6px;font-size:15px}.brandmark{width:37px;height:37px;border-radius:12px;background:var(--lime);display:grid;place-items:center;color:#17220d;font-size:20px;transform:rotate(-8deg)}.brand small{display:block;color:#aab29e;font-size:9px;letter-spacing:2px;font-weight:700;margin-top:3px}.nav{display:flex;gap:7px}.nav button{background:transparent;padding:10px 14px;border-radius:10px;color:#aab2a6;font-size:12px;font-weight:700;transition:.18s}.nav button:hover,.nav button.active{background:#ffffff10;color:var(--lime)}.topright{display:flex;align-items:center;gap:16px}.money{color:var(--lime);font-weight:800;font-size:13px}.avatar{width:36px;height:36px;border-radius:50%;background:linear-gradient(145deg,#f9c38b,#bc684e);display:grid;place-items:center;font-size:20px;border:2px solid #ffffff36}.page{padding-top:28px}.eyebrow{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--lime);font-weight:800}.hero{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:22px}.hero h1{font:800 clamp(32px,4.2vw,55px)/.95 'Barlow Condensed',sans-serif;text-transform:uppercase;letter-spacing:.3px;margin:9px 0 0}.hero p{color:var(--muted);font-size:13px;margin:10px 0 0}.week-pill{background:#ffffff0b;border:1px solid var(--line);border-radius:30px;padding:10px 14px;font-size:11px;color:#bac2b4}.week-pill b{color:var(--lime);margin-left:5px}.grid{display:grid;grid-template-columns:1.55fr .9fr .85fr;gap:16px;align-items:stretch}.card{background:linear-gradient(145deg,#202820,#192019);border:1px solid var(--line);border-radius:17px;overflow:hidden;position:relative}.player-card{min-height:268px;padding:22px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(120deg,#263622,#20291c 60%,#1b211a)}.player-card:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent 50%,#182018aa),radial-gradient(ellipse at 80% 60%,#8fb8521e,transparent 35%);pointer-events:none}.player-info{z-index:1;align-self:stretch;display:flex;flex-direction:column;justify-content:space-between;max-width:65%}.position{font-size:10px;letter-spacing:2px;color:var(--lime);font-weight:800}.player-name{font:900 clamp(37px,5vw,63px)/.83 'Barlow Condensed',sans-serif;text-transform:uppercase;margin-top:12px}.player-sub{font-size:12px;color:#c0c8b7;margin-top:12px}.rating{display:flex;gap:21px;margin-top:20px}.rating b{display:block;font:800 21px 'Barlow Condensed',sans-serif}.rating span{font-size:9px;letter-spacing:1px;color:#9eaa99}.player-figure{z-index:1;align-self:flex-end;height:220px;width:132px;position:relative;margin-right:8px}.player-figure .head{position:absolute;top:3px;left:45px;width:41px;height:48px;border-radius:48% 48% 44% 44%;background:linear-gradient(115deg,#cc895f,#925837);z-index:3}.player-figure .hair{position:absolute;top:1px;left:43px;width:44px;height:15px;background:#302219;border-radius:70% 70% 20% 20%;z-index:4}.player-figure .body{position:absolute;top:44px;left:24px;width:81px;height:102px;border-radius:18px 18px 11px 11px;background:linear-gradient(90deg,#d14a3d,#f2614a 55%,#bf4138);clip-path:polygon(15% 0,85% 0,100% 15%,89% 100%,11% 100%,0 15%)}.player-figure .shirtline{position:absolute;top:48px;left:60px;height:85px;width:4px;background:#f3d09a;z-index:2;opacity:.8}.player-figure .shorts{position:absolute;top:137px;left:25px;width:80px;height:45px;background:#f4f1df;clip-path:polygon(5% 0,95% 0,90% 100%,55% 100%,50% 35%,45% 100%,10% 100%)}.player-figure .leg{position:absolute;top:171px;width:20px;height:39px;background:#ce8c65;border-radius:6px}.player-figure .leg.l{left:42px}.player-figure .leg.r{left:72px}.player-figure .sock{position:absolute;top:194px;width:20px;height:18px;background:#f5f0df}.player-figure .sock.l{left:42px}.player-figure .sock.r{left:72px}.player-figure .boot{position:absolute;top:207px;width:29px;height:11px;background:#192017;border-radius:9px 3px 4px 4px}.player-figure .boot.l{left:34px}.player-figure .boot.r{left:69px}.player-figure .number{position:absolute;top:74px;left:55px;z-index:4;color:#fff4d7;font:800 31px 'Barlow Condensed'}.player-figure .ball{position:absolute;right:-12px;bottom:1px;font-size:23px;filter:drop-shadow(0 3px 2px #111)}.cardpad{padding:20px}.cardhead{display:flex;justify-content:space-between;align-items:center}.cardhead h3{margin:0;font:700 19px 'Barlow Condensed',sans-serif;text-transform:uppercase;letter-spacing:.5px}.cardhead .tiny{font-size:10px;color:var(--muted)}.matchcard{min-height:268px;display:flex;flex-direction:column}.fixture{display:flex;align-items:center;justify-content:center;gap:17px;flex:1;padding-top:10px}.club{display:grid;justify-items:center;gap:9px;font-size:10px;color:#cad2c3;font-weight:700}.crest{width:50px;height:56px;display:grid;place-items:center;clip-path:polygon(0 0,100% 0,91% 75%,50% 100%,9% 75%);background:linear-gradient(140deg,#d85841,#9f2d2b);font:800 24px 'Barlow Condensed'}.crest.away{background:linear-gradient(140deg,#eef0df,#98a188);color:#293428}.vs{font:800 22px 'Barlow Condensed';color:#808b7c}.matchmeta{text-align:center;color:#96a28f;font-size:10px;margin-top:4px}.btn{border-radius:9px;padding:12px 16px;font-size:11px;font-weight:800;letter-spacing:.5px;transition:transform .15s,filter .15s}.btn:hover{transform:translateY(-1px);filter:brightness(1.08)}.btn-primary{background:var(--lime);color:#1b2811}.btn-dark{background:#ffffff12;color:var(--white);border:1px solid #ffffff12}.btn-orange{background:var(--orange);color:#20150f}.matchcard .btn{width:100%;margin-top:14px}.formcard{min-height:268px;padding:20px;display:flex;flex-direction:column}.formlist{display:flex;gap:8px;margin:23px 0 18px}.formdot{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;font-size:11px;font-weight:900}.win{background:#324a28;color:#c5f58a}.draw{background:#51472b;color:#ffdd88}.loss{background:#522e2d;color:#ff9b94}.formcaption{font-size:11px;color:#9da899;line-height:1.5}.streak{margin-top:auto;display:flex;align-items:center;justify-content:space-between;color:#a4afa0;font-size:10px}.streak strong{font:800 27px 'Barlow Condensed';color:var(--lime)}.section-title{font:800 22px 'Barlow Condensed';text-transform:uppercase;letter-spacing:.8px;margin:28px 0 13px}.quickgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:13px}.quick{padding:16px;min-height:116px;cursor:pointer;transition:.18s}.quick:hover{transform:translateY(-3px);border-color:#6b8650;background:#252f23}.quickicon{width:36px;height:36px;border-radius:11px;background:#ffffff0d;display:grid;place-items:center;font-size:19px;margin-bottom:12px}.quick b{font:700 17px 'Barlow Condensed';text-transform:uppercase}.quick span{display:block;font-size:10px;color:var(--muted);margin-top:4px}.dashboard-bottom{display:grid;grid-template-columns:1.2fr .8fr;gap:14px;margin-top:14px}.news{padding:18px 20px}.newsrow{display:flex;gap:12px;align-items:center;padding-top:14px}.newsicon{font-size:21px}.newsrow b{font-size:11px}.newsrow p{margin:3px 0 0;font-size:10px;color:var(--muted)}.contract{padding:18px 20px}.contractline{display:flex;justify-content:space-between;padding-top:14px;font-size:10px;color:var(--muted)}.contractline strong{color:var(--white)}.progress{height:5px;background:#394137;border-radius:9px;margin-top:11px}.progress i{display:block;height:100%;width:48%;background:var(--lime);border-radius:9px}.page-head{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:20px}.page-head h1{font:800 46px/.9 'Barlow Condensed';text-transform:uppercase;margin:8px 0 0}.page-head p{color:var(--muted);font-size:12px;margin:9px 0 0}.subtabs{display:flex;gap:7px;margin-bottom:18px}.subtabs button{padding:9px 14px;border-radius:20px;background:#ffffff0a;color:#aab4a5;font-size:10px;font-weight:700}.subtabs button.active{background:var(--lime);color:#1d2717}.panel{padding:21px}.match-layout{display:grid;grid-template-columns:1fr 280px;gap:15px}.pitch-wrap{position:relative;background:#142018;border:1px solid #394739;border-radius:15px;overflow:hidden;min-height:390px}.pitch-wrap canvas{display:block;width:100%;height:100%;min-height:390px;touch-action:none}.match-overlay{position:absolute;inset:12px 14px auto;display:flex;justify-content:space-between;align-items:center;pointer-events:none}.scoreboard{background:#101611dd;border:1px solid #ffffff22;border-radius:10px;padding:8px 12px;text-align:center;min-width:135px}.scoreboard b{font:800 20px 'Barlow Condensed';letter-spacing:1px}.scoreboard span{display:block;color:#aab5a5;font-size:8px;letter-spacing:1.5px;margin-top:2px}.minute{font-size:10px;color:#e3e9da;background:#101611dd;border-radius:8px;padding:8px 10px}.match-side{display:flex;flex-direction:column;gap:12px}.sidebox{background:#1b231b;border:1px solid var(--line);border-radius:13px;padding:15px}.sidebox h3{font:700 17px 'Barlow Condensed';text-transform:uppercase;margin:0 0 9px}.sidebox p{font-size:10px;line-height:1.5;color:var(--muted);margin:0}.controls{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:11px}.controls button{padding:13px 8px;touch-action:manipulation}.control-row{display:flex;gap:7px}.control-row button{flex:1}.match-status{color:var(--lime);font-weight:800;font-size:11px;margin-top:10px;min-height:18px}.mobile-note{font-size:9px!important;margin-top:9px!important}.end-actions{display:flex;gap:8px;margin-top:10px}.hidden{display:none!important}.country-grid,.club-grid,.shop-grid,.life-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.country-option,.club-option{padding:14px;cursor:pointer;transition:.15s}.country-option:hover,.club-option:hover{border-color:var(--lime)}.country-option.selected,.club-option.selected{border-color:var(--lime);box-shadow:0 0 0 1px var(--lime) inset}.flag{font-size:23px}.country-option strong,.club-option strong{display:block;margin-top:8px;font-size:11px}.country-option small,.club-option small{display:block;color:var(--muted);font-size:9px;margin-top:3px}.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.select{background:#202820;color:var(--white);border:1px solid var(--line);padding:10px 13px;border-radius:9px}.club-option{min-height:133px}.clubcrest{font:900 20px 'Barlow Condensed';background:linear-gradient(145deg,#dd5849,#8b2926);width:38px;height:42px;display:grid;place-items:center;clip-path:polygon(0 0,100% 0,90% 77%,50% 100%,10% 77%)}.offer{font-size:10px;color:var(--lime);font-weight:800;margin-top:10px}.shop-grid{grid-template-columns:repeat(3,1fr)}.item-card{padding:16px;text-align:center}.item-preview{height:105px;background:linear-gradient(145deg,#333d31,#242c23);border-radius:10px;display:grid;place-items:center;font-size:43px;margin-bottom:12px}.item-card h3{font:700 17px 'Barlow Condensed';margin:0}.item-card p{font-size:9px;color:var(--muted);margin:5px 0 12px}.item-card .btn{width:100%}.life-grid{grid-template-columns:repeat(3,1fr)}.life-card{padding:20px;min-height:186px;display:flex;flex-direction:column}.life-card .bigicon{font-size:26px;margin:5px 0 10px}.life-card h3{font:700 20px 'Barlow Condensed';text-transform:uppercase;margin:0}.life-card p{font-size:10px;line-height:1.5;color:var(--muted);margin:7px 0 14px}.life-card .btn{margin-top:auto;align-self:flex-start}.toast{position:fixed;left:50%;bottom:25px;z-index:20;transform:translate(-50%,20px);opacity:0;background:#d3f582;color:#17200f;font-weight:800;font-size:12px;border-radius:10px;padding:12px 19px;box-shadow:0 10px 40px #0008;transition:.25s;pointer-events:none}.toast.show{transform:translate(-50%,0);opacity:1}.modal-backdrop{position:fixed;z-index:15;inset:0;background:#050805ce;display:grid;place-items:center;padding:18px}.modal{width:min(500px,100%);background:#1c251c;border:1px solid #526247;border-radius:17px;padding:24px;box-shadow:0 20px 70px #0009}.modal h2{font:800 32px 'Barlow Condensed';text-transform:uppercase;margin:0}.modal p{font-size:12px;line-height:1.6;color:#aab5a5}.modal-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:18px}.range{width:100%;accent-color:var(--lime)}.hair-row{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.hair-choice{background:#ffffff0b;border:1px solid var(--line);border-radius:10px;padding:10px 12px}.hair-choice.selected{border-color:var(--lime)}.toast,.modal{font-family:'DM Sans',sans-serif}
@media(max-width:980px){.shell{padding:0 22px 30px}.grid{grid-template-columns:1.2fr 1fr}.formcard{grid-column:span 2;min-height:150px}.formlist{margin:14px 0}.quickgrid{grid-template-columns:repeat(2,1fr)}.country-grid,.club-grid{grid-template-columns:repeat(3,1fr)}}
@media(max-width:650px){.shell{padding:0 14px calc(22px + env(safe-area-inset-bottom))}.topbar{height:auto;min-height:64px;flex-wrap:wrap;padding:10px 0;gap:8px}.brand{font-size:13px}.brandmark{width:32px;height:32px}.topright{gap:9px}.nav{order:3;overflow:auto;width:100%;padding-bottom:2px;scrollbar-width:none}.nav button{padding:8px 11px;white-space:nowrap;font-size:10px}.page{padding-top:20px}.hero{align-items:flex-start}.hero h1{font-size:42px}.week-pill{font-size:9px;padding:8px}.grid{grid-template-columns:1fr;gap:11px}.player-card{min-height:225px;padding:18px}.player-figure{height:195px;transform:scale(.88);transform-origin:bottom right;margin-right:-7px}.player-figure .head{top:3px}.player-info{max-width:65%}.player-name{font-size:49px}.rating{gap:14px;margin-top:12px}.rating b{font-size:18px}.matchcard{min-height:225px}.formcard{grid-column:auto;min-height:145px}.quickgrid{gap:9px}.quick{min-height:110px;padding:13px}.dashboard-bottom{grid-template-columns:1fr}.page-head h1{font-size:39px}.match-layout{grid-template-columns:1fr}.pitch-wrap{min-height:330px}.pitch-wrap canvas{min-height:330px}.match-side{display:grid;grid-template-columns:1fr 1fr}.sidebox:first-child{grid-column:span 2}.controls button{padding:14px 5px}.country-grid,.club-grid{grid-template-columns:repeat(2,1fr)}.life-grid{grid-template-columns:1fr 1fr}.life-card{padding:15px;min-height:185px}.shop-grid{grid-template-columns:repeat(2,1fr)}.item-preview{height:82px}.toolbar{align-items:flex-start;gap:8px;flex-wrap:wrap}.end-actions{flex-wrap:wrap}}
@media(max-width:380px){.money{font-size:11px}.life-grid{grid-template-columns:1fr}.quickgrid{grid-template-columns:1fr 1fr}.hero h1{font-size:36px}.country-option{padding:11px}}

const countries=[['🇦🇷','Argentina'],['🇦🇺','Australia'],['🇧🇪','Belgium'],['🇧🇷','Brazil'],['🇨🇦','Canada'],['🇨🇱','Chile'],['🇨🇴','Colombia'],['🇭🇷','Croatia'],['🇩🇰','Denmark'],['🇪🇬','Egypt'],['🇫🇷','France'],['🇩🇪','Germany'],['🇬🇭','Ghana'],['🇮🇹','Italy'],['🇯🇵','Japan'],['🇲🇽','Mexico'],['🇲🇦','Morocco'],['🇳🇱','Netherlands'],['🇳🇿','New Zealand'],['🇳🇬','Nigeria'],['🇳🇴','Norway'],['🇵🇱','Poland'],['🇵🇹','Portugal'],['🇸🇳','Senegal'],['🇰🇷','South Korea'],['🇪🇸','Spain'],['🇸🇪','Sweden'],['🇨🇭','Switzerland'],['🇺🇸','United States'],['🏴','England'],['🏴','Scotland'],['🏴','Wales'],['🏴','Northern Ireland'],['🇺🇦','Ukraine'],['🇺🇾','Uruguay'],['🇹🇷','Türkiye']];
const clubs=[{name:'Northbridge FC',short:'NFC',league:'Premier League',level:4,salary:8400,color:'#d24b3f'},{name:'Royal Madrid',short:'RM',league:'La Liga',level:5,salary:12800,color:'#d5ca91'},{name:'Paris Aurora',short:'PA',league:'Ligue 1',level:5,salary:11900,color:'#5796c4'},{name:'Bayern Nord',short:'BN',league:'Bundesliga',level:5,salary:12400,color:'#d84442'},{name:'Milan Rosso',short:'MR',league:'Serie A',level:4,salary:9500,color:'#c74b40'},{name:'Amsterdam 09',short:'A09',league:'Eredivisie',level:3,salary:7000,color:'#ed8741'},{name:'Lisbon Sporting',short:'LS',league:'Primeira Liga',level:3,salary:6500,color:'#64a763'},{name:'Coastal United',short:'CU',league:'MLS',level:2,salary:5200,color:'#548ac1'}];
const initial={started:false,name:'Alex Morgan',age:19,nation:'England',club:'Northbridge FC',money:12500,salary:8400,week:1,rating:68,energy:76,fitness:72,goals:0,assists:0,played:0,wins:0,streak:0,girlfriend:false,wardrobe:[],outfit:'Classic kit',hair:'Short fade',league:'Premier League',contract:12,season:1,lastResult:'No matches played yet',casinoPlays:0,saveDate:Date.now()};
let s={...initial,...JSON.parse(localStorage.getItem('touchline-save')||'{}')};let screen='home',activeMatch=null,matchLoop=null,toastTimer=null;
const app=document.getElementById('app');function save(){s.saveDate=Date.now();localStorage.setItem('touchline-save',JSON.stringify(s))}function money(n){return '£'+Math.round(n).toLocaleString('en-GB')}function club(){return clubs.find(c=>c.name===s.club)||clubs[0]}function notify(t){const el=document.querySelector('.toast');if(!el)return;el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function shell(content){app.innerHTML=`<div class="shell"><header class="topbar"><div class="brand"><div class="brandmark">✦</div><div>TOUCHLINE<small>PRO CAREER</small></div></div><nav class="nav">${[['home','Career'],['match','Matchday'],['life','My Life'],['clubhouse','Clubhouse'],['profile','Profile']].map(([id,label])=>`<button class="${screen===id?'active':''}" onclick="go('${id}')">${label}</button>`).join('')}</nav><div class="topright"><div class="money">◈ ${money(s.money)}</div><div class="avatar">${s.girlfriend?'🤍':'👤'}</div></div></header><main class="page">${content}</main><div class="toast"></div></div>`;}
function startScreen(){const greeting=s.started?`Welcome back, ${s.name.split(' ')[0]}. Your next chapter starts here.`:'Build your name. Live your life. Own every moment.';shell(`<section class="hero"><div><div class="eyebrow">SEASON ${s.season} · WEEK ${s.week}</div><h1>${s.started?'The road to greatness':'Your career starts now'}</h1><p>${greeting}</p></div><div class="week-pill">WEEKLY PAY <b>${money(s.salary)}</b></div></section><section class="grid"><article class="card player-card"><div class="player-info"><div><div class="position">${s.started?s.nation.toUpperCase()+' · ATTACKING MIDFIELDER':'ACADEMY PROSPECT · #10'}</div><div class="player-name">${s.started?s.name:'ALEX<br>MORGAN'}</div><div class="player-sub">${s.club} &nbsp;·&nbsp; Age ${s.age} &nbsp;·&nbsp; ${s.outfit}</div></div><div class="rating"><div><b>${s.rating}<span style="font-size:10px;color:var(--lime)"> OVR</span></b><span>RATING</span></div><div><b>${s.goals}</b><span>GOALS</span></div><div><b>${s.fitness}%</b><span>FITNESS</span></div></div></div><div class="player-figure"><div class="hair"></div><div class="head"></div><div class="body"></div><div class="shirtline"></div><div class="number">10</div><div class="shorts"></div><div class="leg l"></div><div class="leg r"></div><div class="sock l"></div><div class="sock r"></div><div class="boot l"></div><div class="boot r"></div><div class="ball">⚽</div></div></article><article class="card cardpad matchcard"><div class="cardhead"><h3>Next fixture</h3><span class="tiny">${s.week%2?'LEAGUE':'CUP'}</span></div><div class="fixture"><div class="club"><div class="crest">${club().short}</div>${club().name}</div><div class="vs">VS</div><div class="club"><div class="crest away">${['Rovers FC','City Athletic','Harbor Town','Eastvale'][s.week%4].slice(0,2).toUpperCase()}</div>${['Rovers FC','City Athletic','Harbor Town','Eastvale'][s.week%4]}</div></div><div class="matchmeta">TODAY &nbsp;·&nbsp; ${s.played===0?'FIRST KICKOFF':'MATCHDAY '+(s.played+1)}</d