function renderCreate(){shell(`<section class="hero"><div><div class="eyebrow">A PLAYER'S STORY</div><h1>Write your own legacy</h1><p>Choose your nation, pick a name, and take your first step into the pros.</p></div></section><div class="card panel" style="max-width:900px;margin:auto"><div class="toolbar"><div><div class="eyebrow">01 — YOUR PLAYER</div><h2 style="font:800 27px 'Barlow Condensed';margin:7px 0">Create your pro</h2></div><div class="tiny">Your career autosaves on this device</div></div><label style="display:block;font-size:10px;color:var(--muted);margin:14px 0 6px">PLAYER NAME</label><input id="playerName" maxlength="20" value="Alex Morgan" class="select" style="width:100%;font-size:14px"><label style="display:block;font-size:10px;color:var(--muted);margin:20px 0 6px">CHOOSE YOUR NATION <span style="color:var(--lime)">(${countries.length} available)</span></label><div class="country-grid">${countries.map(([flag,name])=>`<div class="card country-option ${name===s.nation?'selected':''}" onclick="pickNation('${name}',this)"><span class="flag">${flag}</span><strong>${name}</strong><small>National team</small></div>`).join('')}</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:22px;gap:12px;flex-wrap:wrap"><span style="font-size:10px;color:var(--muted)">Start at Northbridge FC · £8,400 weekly wage · Age 19</span><button class="btn btn-primary" onclick="beginCareer()">START MY CAREER &nbsp; →</button></div></div>`)}let selectedNation=s.nation;function pickNation(name,el){selectedNation=name;document.querySelectorAll('.country-option').forEach(x=>x.classList.remove('selected'));el.classList.add('selected')}function beginCareer(){const name=document.getElementById('playerName').value.trim();if(!name){notify('Add a player name first');return}s.name=name;s.nation=selectedNation;s.started=true;save();notify(`Welcome to the pros, ${name.split(' ')[0]}!`);render()}
let keysDown={},moveInterval=null;function renderMatch(){activeMatch={time:0,home:0,away:0,x:360,y:300,bx:410,by:300,hasBall:true,done:false,competition:document.getElementById('competition')?.value||'League',log:'Kick off! Find space and make your mark.'};shell(`<section class="page-head"><div><div class="eyebrow">MATCHDAY ${s.played+1} · ${s.club.toUpperCase()}</div><h1>Make the moment</h1><p>Play the key highlights. Create chances, score goals, and lift your team.</p></div><div class="week-pill">FITNESS <b>${s.fitness}%</b></div></section><div class="toolbar"><div class="subtabs"><button class="active" onclick="setCompetition('League',this)">League</button><button onclick="setCompetition('UEFA Champions League',this)">UEFA Champions League</button><button onclick="setCompetition('World Cup',this)">World Cup</button></div><span class="tiny">Keyboard: WASD / arrows · Space shoots · E passes</span></div><section class="match-layout"><div class="pitch-wrap"><canvas id="pitch"></canvas><div class="match-overlay"><div class="scoreboard"><b id="scoreboard">NFC &nbsp; 0 — 0 &nbsp; ROV</b><span id="compLabel">LEAGUE · 1ST HALF</span></div><div class="minute" id="minute">01′</div></div></div><aside class="match-side"><div class="sidebox"><h3>Match controls</h3><p>Move into space, then take your chance. Your choices shape the highlights.</p><div class="controls"><div class="control-row"><button class="btn btn-dark" onpointerdown="holdMove('up')" onpointerup="stopMove()" onpointerleave="stopMove()">↑</button></div><div></div><button class="btn btn-dark" onpointerdown="holdMove('left')" onpointerup="stopMove()" onpointerleave="stopMove()">←</button><button class="btn btn-dark" onpointerdown="holdMove('down')" onpointerup="stopMove()" onpointerleave="stopMove()">↓</button><button class="btn btn-dark" onpointerdown="holdMove('right')" onpointerup="stopMove()" onpointerleave="stopMove()">→</button></div><div class="controls"><button class="btn btn-primary" onclick="shoot()">⚽ &nbsp; SHOOT</button><button class="btn btn-dark" onclick="passBall()">↗ &nbsp; PASS</button><button class="btn btn-orange" onclick="tackle()">✦ &nbsp; TACKLE</button><button class="btn btn-dark" onclick="playMoment()">⏩ &nbsp; NEXT MOMENT</button></div><p class="mobile-note">Touch and hold to move. Shoot near goal, pass to keep possession.</p></div><div class="sidebox"><h3>Match highlights</h3><p id="matchLog">${activeMatch.log}</p><div class="match-status" id="matchStatus">Ready for kickoff</div><div class="end-actions"><button class="btn btn-dark" onclick="forfeitMatch()">Leave match</button><button class="btn btn-primary hidden" id="continueBtn" onclick="finishMatch()">FULL TIME →</button></div></div></aside></section>`);initPitch();window.onkeydown=e=>{let k=e.key.toLowerCase();keysDown[k]=true;if(k===' '){e.preventDefault();shoot()}if(k==='e')passBall();if(k==='shift')tackle()};window.onkeyup=e=>keysDown[e.key.toLowerCase()]=false;startMatchLoop()}
function setCompetition(c,el){activeMatch.competition=c;document.querySelectorAll('.subtabs button').forEach(b=>b.classList.remove('active'));el.classList.add('active');document.getElementById('compLabel').textContent=c.toUpperCase()+' · 1ST HALF';document.querySelector('.eyebrow').textContent=`${c.toUpperCase()} · ${s.club.toUpperCase()}`}
function startMatchLoop(){clearInterval(matchLoop);matchLoop=setInterval(()=>{if(!activeMatch||activeMatch.done)return;activeMatch.time+=1;if(Math.random()<.17){activeMatch.bx+=Math.random()*100-50;activeMatch.by+=Math.random()*90-45;activeMatch.bx=Math.max(60,Math.min(940,activeMatch.bx));activeMatch.by=Math.max(90,Math.min(510,activeMatch.by));if(!activeMatch.hasBall&&Math.random()<.3){activeMatch.hasBall=true;activeMatch.x=activeMatch.bx;activeMatch.y=activeMatch.by;activeMatch.log='You win the ball back in midfield!';}}if(activeMatch.time>=9)endMatch();updateMatchHud();drawPitch()},1800)}
function playMoment(){if(!activeMatch||activeMatch.done)return;activeMatch.time+=2;activeMatch.x=Math.min(880,activeMatch.x+48);activeMatch.bx=activeMatch.x;activeMatch.by=activeMatch.y;activeMatch.hasBall=true;activeMatch.log=['A neat one-two opens the pitch.','You spot a run down the channel.','The crowd roars as you carry it forward.','A defender closes in — make your move!'][Math.floor(Math.random()*4)];if(activeMatch.time>=9)endMatch();updateMatchHud();drawPitch()}

