/* A focused, cinematic shot replay: CSS perspective keeps the action lightweight on phones. */
.pitch-wrap{position:relative;overflow:hidden}.shot-overlay{position:absolute;inset:0;z-index:4;display:flex;flex-direction:column;justify-content:space-between;overflow:hidden;border-radius:inherit;background:linear-gradient(180deg,#172b3b 0%,#3f6570 44%,#263d2b 45%,#102117 100%);animation:shot-enter .22s ease-out}.shot-topline{position:relative;z-index:2;display:flex;justify-content:space-between;align-items:center;padding:12px 14px;font-size:10px;font-weight:900;letter-spacing:1.6px;color:#fff;text-shadow:0 2px 6px #000}.shot-topline button{padding:10px 13px;border-radius:9px;background:#111b20cc;color:#fff;font-size:10px;font-weight:800;touch-action:manipulation}.shot-stage{position:absolute;inset:0;overflow:hidden;perspective:700px}.shot-stands{position:absolute;top:15%;left:10%;width:80%;color:#e8f4dc;font-size:clamp(9px,2vw,15px);font-weight:900;letter-spacing:clamp(3px,1vw,10px);text-align:center;text-shadow:0 2px 8px #111;opacity:.76}.shot-pitch{position:absolute;left:-18%;right:-18%;height:72%;bottom:-27%;border:2px solid #d5efcc99;border-radius:50% 50% 0 0/24% 24% 0 0;background:repeating-linear-gradient(90deg,#1d542f 0 12%,#28653a 12% 24%);transform:rotateX(58deg);transform-origin:center top;box-shadow:0 -12px 35px #0e2018}.shot-goalframe{position:absolute;top:24%;right:13%;width:34%;height:38%;border:5px solid #f4f4e5;border-bottom-width:3px;transform:perspective(500px) rotateY(-12deg);box-shadow:0 5px 18px #07100c99}.shot-net{position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent 0 13px,#f2f2dc55 14px 15px),repeating-linear-gradient(90deg,transparent 0 17px,#f2f2dc55 18px 19px)}.shot-keeper{position:absolute;z-index:2;left:42%;top:33%;font-size:clamp(26px,6vw,52px);filter:drop-shadow(0 3px 4px #111);animation:keeper-react .65s .55s ease-out both}.shot-player{position:absolute;z-index:2;left:19%;bottom:18%;width:48px;height:110px;filter:drop-shadow(0 5px 4px #09140d99);animation:player-strike .72s .1s ease-out both}.shot-head{position:absolute;left:17px;top:0;width:25px;height:25px;border-radius:50%;background:#dfad84;border:2px solid #714c38}.shot-body{position:absolute;left:9px;top:23px;width:42px;height:48px;border-radius:13px 13px 7px 7px;background:linear-gradient(90deg,#e45c45,#b93332);border:2px solid #f4d2a4}.shot-body:after{content:'10';position:absolute;inset:9px 0 auto;text-align:center;color:#fff;font:900 15px 'Barlow Condensed',sans-serif}.shot-leg{position:absolute;left:30px;top:64px;width:15px;height:48px;border-radius:9px;background:linear-gradient(#e9eadb 0 75%,#ef6d4e 76%);transform-origin:top center;animation:leg-kick .65s .16s ease-in-out both}.shot-ball{position:absolute;z-index:3;left:34%;bottom:17%;font-size:clamp(24px,5vw,39px);filter:drop-shadow(0 6px 3px #10151099);animation:ball-flight .85s .36s cubic-bezier(.28,.65,.31,1) both}.shot-save .shot-ball{animation-name:ball-save}.shot-flash{position:absolute;z-index:3;right:24%;top:32%;font-size:42px;color:var(--lime);text-shadow:0 0 20px #fff;opacity:0;transform:scale(.3)}.shot-goal .shot-flash{animation:goal-flash .5s 1.05s ease-out}.shot-callout{position:absolute;z-index:4;bottom:15px;left:50%;transform:translateX(-50%);white-space:nowrap;padding:9px 16px;border:1px solid #ffffff44;border-radius:999px;background:#101810df;color:#fff;font-size:clamp(11px,2.4vw,16px);font-weight:900;letter-spacing:1.4px;box-shadow:0 5px 22px #0008}.shot-result .shot-callout{color:var(--lime)}
@keyframes shot-enter{from{opacity:0;transform:scale(.98)}to{opacity:1;transform:scale(1)}}@keyframes player-strike{0%{transform:translateX(0) rotate(0)}40%{transform:translateX(9px) rotate(-8deg)}100%{transform:translateX(17px) rotate(4deg)}}@keyframes leg-kick{0%,30%{transform:rotate(-25deg)}65%{transform:rotate(58deg)}100%{transform:rotate(17deg)}}@keyframes ball-flight{0%{transform:translate3d(0,0,0) scale(1)}45%{transform:translate3d(15vw,-14vh,65px) scale(.8)}100%{transform:translate3d(43vw,-31vh,120px) scale(.48)}}@keyframes ball-save{0%{transform:translate3d(0,0,0) scale(1)}50%{transform:translate3d(17vw,-13vh,65px) scale(.8)}100%{transform:translate3d(37vw,-17vh,100px) scale(.55) rotate(240deg)}}@keyframes keeper-react{from{transform:translateX(0) rotate(0)}to{transform:translateX(-24px) rotate(-22deg)}}@keyframes goal-flash{0%{opacity:0;transform:scale(.2) rotate(-25deg)}45%{opacity:1;transform:scale(1.5) rotate(12deg)}100%{opacity:0;transform:scale(2) rotate(25deg)}}
@media(max-width:650px){.shot-goalframe{right:10%;width:39%;height:34%;top:27%}.shot-player{left:13%;bottom:19%;transform:scale(.86);transform-origin:bottom left}.shot-ball{left:31%;bottom:19%}.shot-stands{top:18%}.shot-callout{bottom:12px}.shot-topline{padding:9px 10px}}
@media(prefers-reduced-motion:reduce){.shot-overlay,.shot-player,.shot-leg,.shot-ball,.shot-keeper,.shot-flash{animation-duration:.01ms!important;animation-delay:0ms!important}}

