 function casino(){if(s.money<100){notify('You need at least £100 to play');return}modal('Coin flip',`<p>Purely fictional in-game credits. Choose your stake carefully; the game can take your stake or double it.</p><label style="font-size:11px">STAKE: <b id="stakeValue">£100</b></label><input id="stake" class="range" type="range" min="100" max="${Math.min(2000,s.money)}" step="100" value="100" oninput="document.getElementById('stakeValue').textContent='£'+this.value">`,'<button class="btn btn-dark" onclick="closeModal()">WALK AWAY</button><button class="btn btn-orange" onclick="flipCoin()">FLIP COIN</button>')}function flipCoin(){let stake=Number(document.getElementById('stake')?.value||100);if(!spend(stake)){closeModal();return}s.casinoPlays++;let win=Math.random()<.48;if(win)s.money+=stake*2;save();closeModal();notify(win?`Heads! You won ${money(stake)}.`:`Tails — you lost ${money(stake)}.`);renderLife()}
 let clubhouseTab='transfers';function clubTab(tab){clubhouseTab=tab;renderClubhouse(tab)}function renderClubhouse(tab='transfers'){clubhouseTab=tab;const tabs=[['transfers','Transfer market'],['mall','The mall'],['hair','Style studio']];let content='';if(tab==='transfers'){content=`<div class="toolbar"><div><b style="font-size:12px">Find your next chapter</b><div class="tiny" style="margin-top:5px">Offers are for your player. Weekly wages arrive after each match.</div></div><span class="tiny">${s.league}</span></div><div class="club-grid">${clubs.map(c=>{let req=c.level*13+2,ok=s.rating>=req||c.name===s.club;return `<article class="card club-option ${c.name===s.club?'selected':''}"><div class="clubcrest" style="background:linear-gradient(145deg,${c.color},#252b22)">${c.short.slice(0,2)}</div><strong>${c.name}${c.name===s.club?' · CURRENT':''}</strong><small>${c.league} · ${c.level}★</small><div class="offer">${money(c.salary)} / week</div><button class="btn ${ok?'btn-primary':'btn-dark'}" style="width:100%;margin-top:10px" ${ok?'':'disabled'} onclick="signWith('${c.name}')">${c.name===s.club?'SIGNED':'ACCEPT OFFER'}</button>${ok?'':`<small style="color:var(--orange)">Needs ${req} OVR</small>`}</article>`}).join('')}</div>`}else if(tab==='mall'){const items=[['Away Day Hoodie','🧥',680,'Streetwear'],['Neon Training Top','👕',520,'Performance'],['City Runner Sneakers','👟',890,'Footwear'],['Matchday Jacket','🧢',740,'Outerwear'],['Vintage Club Scarf','🧣',260,'Accessories'],['Lime Boot Collection','🥾',1100,'Footwear']];content=`<div class="toolbar"><div><b style="font-size:12px">Wear it your way</b><div class="tiny" style="margin-top:5px">Buy a look and wear it on your player profile.</div></div><span class="money">◈ ${money(s.money)}</span></div><div class="shop-grid">${items.map(([name,icon,price,category])=>{let owned=s.wardrobe.includes(name),worn=s.outfit===name;return `<article class="card item-card"><div class="item-preview">${icon}</div><h3>${name}</h3><p>${category} · ${worn?'NOW WEARING':owned?'IN YOUR WARDROBE':money(price)}</p><button class="btn ${worn?'btn-dark':'btn-primary'}" onclick="${owned?`wear('${name}')`:`buyClothes('${name}',${price})`}">${worn?'WORN':owned?'WEAR IT':'BUY ITEM'}</button></article>`}).join('')}</div>`}else{const styles=['Short fade','Curly crop','Slick back','Buzz cut','Long waves','Braided'];content=`<div class="toolbar"><div><b style="font-size:12px">Fresh cut, fresh start</b><div class="tiny" style="margin-top:5px">Try a new hairstyle for £180. Your choice is saved to your look.</div></div><span class="tiny">CURRENT: ${s.hair}</span></div><div class="hair-row">${styles.map((h,i)=>`<button class="hair-choice ${s.hair===h?'selected':''}" onclick="chooseHair('${h}')"><span style="font-size:23px">${['✂️','🌀','💈','🪒','〰️','〽️'][i]}</span><br><span style="font-size:10px">${h}</span></button>`).join('')}</div><div class="card panel" style="margin-top:17px"><div class="player-figure" style="margin:auto;height:220px"><div class="hair"></div><div class="head"></div><div class="body"></div><div class="shirtline"></div><div class="number">10</div><div class="shorts"></div><div class="leg l"></div><div class="leg r"></div><div class="sock l"></div><div class="sock r"></div><div class="boot l"></div><div class="boot r"></div></div></div>`}shell(`<section class="page-head"><div><div class="eyebrow">YOUR CAREER · YOUR CALL</div><h1>Clubhouse</h1><p>Build your future, find your look, and make the club feel like home.</p></div><div class="week-pill">WEEKLY WAGE <b>${money(s.salary)}</b></div></section><div class="subtabs">${tabs.map(([id,n])=>`<button class="${tab===id?'active':''}" onclick="clubTab('${id}')">${n}</button>`).join('')}</div><section class="card panel">${content}</section>`)}function signWith(name){let c=clubs.find(x=>x.name===name);if(!c)return;if(s.rating<c.level*13+2){notify('Keep improving your rating to unlock this offer');return}if(name===s.club){notify('You already play here');return}moda