import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const cfg=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
const browser=await chromium.launch(cfg.browser.launchOptions);
const page=await browser.newPage({viewport:{width:1440,height:900}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://127.0.0.1:8765');
await page.evaluate(()=>localStorage.setItem('touchline-save',JSON.stringify({started:true,name:'Test Player',nation:'England',club:'Northbridge FC',money:12500,salary:8400,week:1,rating:68,energy:76,fitness:72,goals:0,assists:0,played:0,wins:0,streak:0,girlfriend:false,wardrobe:[],outfit:'Classic kit',hair:'Short fade',league:'Premier League',contract:12,season:1,lastResults:[]})));
await page.reload();
await page.locator('.nav button').filter({hasText:'Matchday'}).click();
await page.waitForSelector('#pitch');
console.log('match',await page.locator('.scenario-picker label').innerText(),'options',await page.locator('#scenarioSelect option').count(),'canvas',await page.locator('#pitch').boundingBox());
await page.locator('#scenarioSelect').selectOption('225');
console.log('preview',await page.locator('#scenarioName').innerText(),'objective',await page.locator('#scenarioObjective').innerText());
await page.getByRole('button',{name:'LOAD SCENARIO'}).click();
console.log('loaded status',await page.locator('#scenarioName').innerText(),'score',await page.locator('#scoreboard').innerText(),'minute',await page.locator('#minute').innerText());
await page.screenshot({path:'/tmp/opencode/match-desktop.png'});
await page.setViewportSize({width:390,height:844});
await page.waitForTimeout(300);
console.log('mobile pitch',await page.locator('#pitch').boundingBox(),'page width',await page.evaluate(()=>document.documentElement.scrollWidth));
await page.screenshot({path:'/tmp/opencode/match-mobile.png'});
console.log('errors',errors);
await browser.close();
