const { createRequire } = require('node:module');
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
  const config = JSON.parse(fs.readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
  const browser = await chromium.launch(config.browser.launchOptions);
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:3000', { waitUntil: 'load' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'load' });
  await page.locator('#playerName').fill('Test Striker');
  await page.locator('button', { hasText: 'START MY CAREER' }).click();
  await page.getByText('Matchday', { exact: true }).click();
  const count = await page.locator('#scenarioSelect option').count();
  if (count < 201) throw new Error(`Expected >200 scenarios, got ${count}`);
  await page.locator('#scenarioSelect').selectOption({ label: /Find the far corner/ }).catch(async () => {
    await page.locator('#scenarioSelect').selectOption('9');
  });
  await page.locator('button', { hasText: 'LOAD SCENARIO' }).click();
  const title = await page.locator('#scenarioName').textContent();
  const objective = await page.locator('#scenarioObjective').textContent();
  if (!title.includes('SCENARIO') || !objective.includes('Far-corner')) throw new Error(`Scenario load failed: ${title} / ${objective}`);
  if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
  console.log(JSON.stringify({ scenarioCount: count, loaded: title.trim(), objective: objective.trim(), browserErrors: errors.length }));
  await browser.close();
})().catch(e => { console.error(e); process.exitCode = 1; });
