function renderDrive(){driveState={distance:0,carX:500,speed:1,obstacles:[],spawn:0,last:0,done:false,crashFlash:0};shell(`<section class="page-head"><div><div class="eyebrow">MATCHDAY ROAD TRIP</div><h1>Drive to the stadium</h1><p>Steer through traffic and reach the ground before kickoff. Use ← →, A/D, or the wheel controls.</p></div><div class="week-pill">DESTINATION <b>TOUCHLINE ARENA</b></div></section><section class="activity-layout"><div class="activity-stage"><canvas id="driveCanvas" aria-label="Driving game"></canvas><div class="activity-hud"><b id="driveDistance">0 m / 1,200 m</b><span id="driveStatus">ENGINE READY</span></div></div><aside class="sidebox activity-side"><div class="eyebrow">THE JOURNEY</div><h3>Kickoff is waiting</h3><p>Keep your car between the road lines. Traffic will slow you down if you clip it.</p><div class="drive-controls"><button class="btn btn-dark" onpointerdown="holdDrive('left')" onpointerup="stopDrive()" onpointerleave="stopDrive()">← STEER LEFT</button><button class="btn btn-dark" onpointerdown="holdDrive('right')" onpointerup="stopDrive()" onpointerleave="stopDrive()">STEER RIGHT →</button></div><button class="btn btn-primary" onclick="resetDrive()">START DRIVE</button></aside></section>`);initDrive()}
