function renderDrive(){driveState={started:false,finished:false,lane:1,distance:0,speed:72,traffic:[],spawnIn:1.2,lastTime:0,crashCooldown:0};driveKeys={};shell(`<section class="page-head"><div><div class="eyebrow">MATCHDAY ${s.played+1} · ROAD TO THE STADIUM</div><h1>Drive to the game</h1><p>Weave through traffic and make kickoff. Use ← / → or the on-screen controls to change lanes.</p></div><div class="week-pill">DESTINATION <b>${escapeHTML(s.club)}</b></div></section><section class="drive-layout"><article class="card drive-card"><div class="drive-hud"><span id="driveStatus">READY TO DEPART</span><span>ROAD SPEED <b id="driveSpeed">72 km/h</b></span><span>JOURNEY <b id="driveDistance">0 / 1,800 m</b></span></div><canvas id="driveCanvas" aria-label="Driving road game"></canvas><div class="drive-progress"><i id="driveProgress"></i></div><div class="drive-controls"><button class="btn btn-dark" onclick="steerDrive(-1)" aria-label="Steer left">← LEFT</button><button class="btn btn-primary" id="driveStart" onclick="startDrive()">START DRIVE</button><button class="btn btn-dark" onclick="steerDrive(1)" aria-label="Steer right">RIGHT →</button></div><p class="tiny drive-help">Avoid the other cars. A collision slows you down; reach the stadium to continue to Matchday.</p></article><aside class="card panel drive-aside"><div class="eyebrow">YOUR FIXTURE</div><h2>${escapeHTML(s.club)}</h2><p>It is matchday. Take the road to the stadium, then step onto the pitch.</p><div class="contractline"><span>Kickoff</span><strong>Today · 15:00</strong></div><div class="contractline"><span>Fitness</span><strong>${s.fitness}%</strong></div><button class="btn btn-dark" style="width:100%;margin-top:14px" onclick="go('home')">BACK TO CAREER</button></aside></section>`);const canvas=document.getElementById('driveCanvas');if(!canvas)return;canvas.addEventListener('pointerdown',e=>{if(!driveState?.started||driveState.finished)return;const r=canvas.getBoundingClientRect();steerDrive((e.clientX-r.left)<r.width/2?-1:1)});drawDrive()}
function startDrive(){if(!driveState||driveState.finished)return;driveState.started=true;driveState.lastTime=performance.now();const btn=document.getElementById('driveStart');if(btn){btn.textContent='DRIVING…';btn.disabled=true}window.addEventListener('keydown',driveKeyDown);window.addEventListener('keyup',driveKeyUp);driveFrame=requestAnimationFrame(updateDrive);updateDriveHud()}
function driveKeyDown(e){if(screen!=='drive'||!driveState?.started||driveState.finished)return;const k=e.key.toLowerCase();if(['arrowleft','a'].includes(k)){e.preventDefault();if(!e.repeat)steerDrive(-1)}else if(['arrowright','d'].includes(k)){e.preventDefault();if(!e.repeat)steerDrive(1)}else if(['arrowup','w'].includes(k)){e.preventDefault();driveKeys.accelerate=true}else if(['arrowdown','s'].includes(k)){e.preventDefault();driveKeys.brake=true}}
function driveKeyUp(e){const k=e.key.toLowerCase();if(['arrowup','w'].includes(k))driveKeys.accelerate=false;if(['arrowdown','s'].includes(k))driveKeys.brake=false}
function steerDrive(direction){if(!driveState?.started||driveState.finished)return;driveState.lane=Math.max(0,Math.min(2,driveState.lane+direction));drawDrive()}
function updateDrive(){if(screen!=='drive'||!driveState?.started||driveState.finished)return;const now=performance.now(),dt=Math.min(.05,Math.max(0,(now-driveState.lastTime)/1000));driveState.lastTime=now;driveState.speed=Math.max(35,Math.min(130,driveState.speed+(driveKeys.accelerate?42:driveKeys.brake?-60:-6)*dt));driveState.distance+=driveState.speed/3.6*4*dt;driveState.spawnIn-=dt;driveState.crashCooldown=Math.max(0,driveState.crashCooldown-dt);if(driveState.spawnIn<=0){driveState.traffic.push({lane:Math.floor(Math.random()*3),y:-45});driveState.spawnIn=.9+Math.random()*.7}driveState.traffic.forEach(car=>car.y+=(125+driveState.speed*.65)*dt);driveState.traffic=driveState.traffic.filter(car=>car.y<470);for(const car of driveState.traffic){if(car.lane===driveState.lane&&car.y>330&&car.y<405&&driveState.crashCooldown===0){driveState.speed=Math.max(35,driveState.speed-30);driveState.crashCooldown=1.1;car.y=450;notify('Traffic bump — watch the road!')}}if(driveState.distance>=1800){driveState.distance=1800;driveState.finished=true;window.removeEventListener('keydown',driveKeyDown);window.removeEventListener('keyup',driveKeyUp);const status=document.getElementById('driveStatus'),btn=document.getElementById('driveStart');if(status)status.textContent='ARRIVED AT THE STADIUM';if(btn){btn.textContent='CONTINUE TO MATCHDAY →';btn.disabled=false;btn.onclick=()=>go('match')}notify('You made it to the stadium — kickoff is next!')}updateDriveHud();drawDrive();if(!driveState.finished)driveFrame=requestAnimationFrame(updateDrive)}
function updateDriveHud(){if(!driveState)return;const speed=document.getElementById('driveSpeed'),distance=document.getElementById('driveDistance'),progress=document.getElementById('driveProgress'),status=document.getElementById('driveStatus');if(speed)speed.textContent=`${Math.round(driveState.speed)} km/h`;if(distance)distance.textContent=`${Math.floor(driveState.distance).toLocaleString()} / 1,800 m`;if(progress)progress.style.width=`${Math.min(100,driveState.distance/18)}%`;if(status&&driveState.started&&!driveState.finished)status.textContent='ON THE ROAD · AVOID TRAFFIC'}
