yle='#ff5a47';g.fillRect(px-17,387,8,7);g.fillRect(px+9,387,8,7);g.fillStyle='#f6f1dc';g.font='bold 11px sans-serif';g.fillText('YOU',px,378);g.setTransform(1,0,0,1,0,0)}
