n{padding:10px 8px;font-size:8px}.scenario-caption{font-size:9px}.scenario-goal{grid-column:1/-1}}
/* Swipe-first match HUD */
.pitch-3d{background:linear-gradient(180deg,#263945 0%,#142018 38%);box-shadow:inset 0 0 40px #07100b66}
.pitch-3d canvas{display:block}
.swipe-tip{position:absolute;left:12px;bottom:12px;z-index:2;max-width:calc(100% - 24px);padding:8px 11px;border:1px solid #ffffff24;border-radius:9px;background:#101611d9;color:#eaf1df;font-size:10px;font-weight:700;pointer-events:none;backdrop-filter:blur(8px)}
.match-action-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin-top:12px}
.match-action-row .btn{min-width:0;padding:11px 4px;font-size:9px;white-space:nowrap;touch-action:manipulation}
@media(max-width:650px){.swipe-tip{left:9px;bottom:9px;font-size:9px}.match-action-row{gap:7px}.match-action-row .btn{padding:12px 5px;font-size:10px}}
@media(max-width:380px){.match-action-row{gap:5px}.match-action-row .btn{padding:11px 2px;font-size:9px}}

