@media(max-width:380px){.match-action-row{gap:5px}.match-action-row .btn{padding:11px 2px;font-size:9px}}
/* Road-trip and technical-training activities */
.drive-layout,.training-layout{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(230px,.75fr);gap:14px;align-items:start}
.drive-card,.training-card{padding:16px;min-width:0}
.drive-hud,.training-hud{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:4px 2px 12px;color:var(--muted);font-size:9px;font-weight:800;letter-spacing:.6px}
.drive-hud b,.training-hud b{color:var(--lime);font-size:12px}
#driveCanvas,#trainingCanvas{display:block;width:100%;height:auto;aspect-ratio:800/420;border:1px solid #ffffff20;border-radius:12px;background:#202820;touch-action:pan-y}
#trainingCanvas{aspect-ratio:800/360;touch-action:none;cursor:crosshair}
.drive-progress{height:6px;margin:12px 0;background:#ffffff14;border-radius:9px;overflow:hidden}
.drive-progress i{display:block;width:0;height:100%;background:var(--lime);border-radius:inherit;transition:width .12s linear}
.drive-controls{display:grid;grid-template-columns:1fr 1.4fr 1fr;gap:8px}
.drive-pedals,.training-controls{display:flex;gap:8px;margin-top:8px}
.drive-pedals>* ,.training-controls>*{flex:1;touch-action:manipulation}
.drive-help{text-align:center;margin:10px 0 0}
.drive-aside h2,.training-layout aside h2{font:800 26px 'Barlow Condensed';margin:12px 0 6px}
.drive-aside p,.training-layout aside p{font-size:11px;color:var(--muted);line-height:1.7}
.training-card>.tiny{text-align:center;margin:10px 0 0}
@media(max-width:850px){.drive-layout,.training-layout{grid-template-columns:1fr}.drive-aside,.training-layout aside{display:none}}
@media(max-width:520px){.drive-card,.training-card{padding:10px}.drive-hud,.training-hud{font-size:8px;gap:5px}.drive-controls{grid-template-columns:1fr 1.3fr 1fr;gap:5px}.drive-controls .btn,.drive-pedals .btn,.training-controls .btn{padding:11px 5px;font-size:9px}.drive-pedals,.training-controls{gap:6px}}

